   var selection=moving?member:((object[])group["Selections"]).Cast<Dictionary<string,object>>().First();var old=(Component2)Resolve(model,(string)selection["ComponentReference"]);var oldId=old.GetID();var oldName=old.Name2;var next=side=="rl"?p.Left:p.Right;var transform=side=="rl"?p.LeftTransform:p.Transform;
   Console.WriteLine("Replacing geometry in existing "+side+" "+p.Role);Activate(model);model.ClearSelection2(true);if(!old.Select4(false,null,false))throw new Exception("Cannot select existing role");
   if(!((AssemblyDoc)model).ReplaceComponents2(next,"Default",false,0,false))throw new Exception("Native replacement rejected "+p.Role);
   var c=Components().Single(v=>string.Equals(v.GetPathName(),next,StringComparison.OrdinalIgnoreCase));c.Transform2=(MathTransform)((MathUtility)app.GetMathUtility()).CreateTransform(transform);c.Name2=oldName;
   var newSelections=RearSelections(c);if(newSelections.Length==0)throw new Exception("Replacement has no bodies");
   if(moving){RearBind(member,newSelections);member["ComponentReference"]=Ref(model,c);member["Part"]=next;member["PlacementFixed"]=c.IsFixed();var appearance=(Dictionary<string,object>)group["AppearanceCoilover"];var piece=RearArray(appearance,"Pieces").Single(v=>object.Equals(v["Kind"],p.Role));RearBind(piece,newSelections);piece["SourceDocument"]=record.Copy;piece["Configuration"]="Default";}
   else {RearBind(group,newSelections);group["CadSourceDocument"]=record.Copy;group["Configuration"]="Default";if(group.ContainsKey("AppearanceSelections")&&group["AppearanceSelections"]!=null){group["AppearanceSelections"]=newSelections;group["AppearanceSourceDocument"]=record.Copy;group["AppearanceDirectory"]=null;}}
   var row=new RearInstalled{Side=side,Role=p.Role,GroupId=(string)group["Id"],MemberId=member==null?null:(string)member["Id"],OldName=oldName,OldId=oldId,Id=c.GetID(),Path=next,Transform=transform};installed.Add(row);
   foreach(var coil in groups.Where(g=>object.Equals(g["MvpRole"],"rl_spring_damper")||object.Equals(g["MvpRole"],"rr_spring_damper"))){RearBind(coil,members.Where(m=>object.Equals(m["ComponentId"],coil["Id"])).SelectMany(m=>(object[])m["Selections"]).ToArray());coil["CadSourceDocument"]=record.Copy;}
   workspace["ScanHash"]=null;workspace["ScanStamp"]=-1;workspace["ScanDocument"]=null;Save(model);File.WriteAllText(record.Copy+".beamng-project.json",json.Serialize(project));Write("rear-installed.json",installed);
   if(Components().Length!=count)throw new Exception("Native replacement changed companion structure");Console.WriteLine("Installed "+side+" "+p.Role+": "+newSelections.Length+" bodies; instance "+oldId+" -> "+c.GetID());
  }
  instances=Components().ToDictionary(c=>c.GetID());CheckOriginals();Write("rear-geometry-complete.json",new{instances=count,logical_groups=groups.Length,changed_roles=installed.Count,originals_unchanged=true});Console.WriteLine("PASS rear geometry installed with companion structure preserved");
 }
