   Action<string,string,string,string,double[],double[]> mate=(name,a,c,kind,point,axis)=>{
    var plan=new MatePlan{Name=side.ToUpperInvariant()+"_donor_"+name,Source=name,Type=0,Entities=new EntityPlan[2]};var roles=new[]{a,c};for(int i=0;i<2;i++){var owner=owners[roles[i]];var inverse=(MathTransform)instances[owner].Transform2.Inverse();plan.Entities[i]=new EntityPlan{Owner=owner,Kind=kind,Source=plan.Name+"_"+i,Point=Map(reflect(point),inverse,false),Axis=Map(reflect(axis??new[]{0.0,1,0}),inverse,true)};}b.Mates.Add(plan);
   };
