   Action<string,string,string,double[],double[]> hinge=(name,a,c,p,axis)=>{mate(name+"_axis",a,c,"axis",p,axis);mate(name+"_seat",a,c,"datum_plane",p,axis);};
   var upper=new[]{.6338570071264096,.0167691498488134,-1.8468833499936097};var lower=new[]{.6341763415639443,-.1349368961339421,-1.8443156444257205};
   var shockTop=new[]{.458465030767677,.5898661073201716,-1.3946224725495762};var shockBottom=new[]{.5404228600216749,.02105401123884443,-1.5638594228337799};var shockAxis=Unit(Sub(shockTop,shockBottom));
   ball("trailing_arm_ball","frame","trailing_arm",new[]{.40005,.0762,-1.1259310840706043});
   ball("upper_radius_inner","frame","upper_radius_rod",new[]{.1397,.18415,-1.923034});ball("upper_radius_outer","trailing_arm","upper_radius_rod",new[]{.6330608081302492,.0179864728386218,-1.9123904459715015});
   ball("lower_radius_inner","frame","lower_radius_rod",new[]{.1397,.034925,-1.897634});ball("lower_radius_outer","trailing_arm","lower_radius_rod",new[]{.633256365570785,-.1309977043094391,-1.8971239027543032});
   hinge("upright_bearings","trailing_arm","upright",upper,Unit(Sub(upper,lower)));
   ball("toe_inner","frame","toe_link",new[]{.1143,.0889,-1.992884});ball("toe_outer","upright","toe_link",new[]{.656860598380231,-.07289911410654085,-1.91502968888222});
   ball("damper_top","frame","housing",shockTop);ball("damper_bottom","trailing_arm","shaft",shockBottom);mate("damper_slide","housing","shaft","axis",shockTop,shockAxis);hinge("spring_seat","housing","spring",shockTop,shockAxis);
   hinge("wheel_bearing","upright","wheel",new[]{.72152950212328,-.0596658856864762,-1.8467263824477451},new[]{-.9999032930330191,-.00187150947661895,.0137804946937103});
  }return b;
