 static void RearRetireReplacedMate(){
  var old=Mates().SingleOrDefault(p=>p.Item1.Name=="Coincident27");if(old==null)return;
  var es=Enumerable.Range(0,old.Item2.GetMateEntityCount()).Select(old.Item2.MateEntity).ToArray();
  if(es.Length!=2||!es.Any(e=>e.ReferenceComponent!=null&&e.ReferenceComponent.GetID()==105)||!es.Any(e=>e.Reference is Feature&&((Feature)e.Reference).Name=="RL Trailing Arm Mount"))throw new Exception("Unexpected old rear mate; refusing removal");
  if(!Mates().Any(p=>p.Item1.Name=="RL_donor_trailing_arm_ball"))throw new Exception("Replacement pivot mate must exist before retiring original");
  Write("rear-retired-mate.json",new{name=old.Item1.Name,reason="Original RL trailing-arm pivot references replaced geometry; superseded by donor-equivalent ball pivot",replacement="RL_donor_trailing_arm_ball"});
  model.ClearSelection2(true);if(!old.Item1.Select2(false,0)||!model.Extension.DeleteSelection2(0))throw new Exception("Could not remove superseded rear pivot mate");model.EditRebuild3();Save(model);Console.WriteLine("Retired superseded rear pivot mate; front mates preserved");
 }
 static void RearAudit(){
  var rows=new List<object>();foreach(var p in Mates()){var es=new List<object>();for(int i=0;i<p.Item2.GetMateEntityCount();i++){var e=p.Item2.MateEntity(i);object reference=null;string kind=null;try{reference=e.Reference;if(reference is Feature)kind=((Feature)reference).Name;}catch{}var c=e.ReferenceComponent;es.Add(new{component=c==null?null:c.Name2,id=c==null?-1:c.GetID(),reference_present=reference!=null,feature=kind,parameters=e.EntityParams,reference_type=e.ReferenceType2});}bool warning;var error=p.Item1.GetErrorCode2(out warning);rows.Add(new{name=p.Item1.Name,type=p.Item2.Type,error=error,warning=warning,suppressed=p.Item1.IsSuppressed(),entities=es});}
  Write("rear-mate-audit.json",rows);Console.WriteLine("Audited "+rows.Count+" mates; failures="+MateFailures());
 }
 static void RearReferences(Blueprint blueprint,string path){
  foreach(var batch in blueprint.Mates.SelectMany(m=>m.Entities).Where(e=>string.IsNullOrEmpty(e.NativeReference)).GroupBy(e=>e.Owner)){
   Console.WriteLine("Preparing joint references for owner "+batch.Key);var doc=Owner(batch.Key);Activate(doc);Console.WriteLine("Activated "+doc.GetTitle());doc.ClearSelection2(true);var manager=doc.SketchManager;manager.Insert3DSketch(true);var add=manager.AddToDB;var entries=new List<Tuple<EntityPlan,object,SketchPoint[]>>();
   try{manager.AddToDB=true;foreach(var e in batch){object result;var points=new List<SketchPoint>();if(e.Kind=="axis"){var a=Add(e.Point,Mul(Unit(e.Axis),-.01));var c=Add(e.Point,Mul(Unit(e.Axis),.01));var line=manager.CreateLine(a[0],a[1],a[2],c[0],c[1],c[2]);line.ConstructionGeometry=true;FixReference(doc,line);result=line;}else{var coordinates=new List<double[]>{e.Point};if(e.Kind=="datum_plane"){var n=Unit(e.Axis);var u=Unit(Cross(n,Math.Abs(n[0])<.9?new[]{1.0,0,0}:new[]{0.0,1,0}));coordinates.Add(Add(e.Point,Mul(u,.01)));coordinates.Add(Add(e.Point,Mul(Cross(n,u),.01)));}foreach(var p in coordinates){var point=manager.CreatePoint(p[0],p[1],p[2]);FixReference(doc,point);points.Add(point);}result=points[0];}entries.Add(Tuple.Create(e,result,points.ToArray()));}}
   finally{manager.AddToDB=add;manager.Insert3DSketch(true);}var feature=doc.FeatureByPositionReverse(0) as Feature;if(feature!=null)feature.Name="Rear_donor_joint_centers";
   foreach(var entry in entries){var e=entry.Item1;var entity=entry.Item2;if(e.Kind=="axis"){doc.ClearSelection2(true);if(!Select(entity,false,0)||!doc.InsertAxis2(true))throw new Exception("Cannot create rear axis");entity=doc.FeatureByPositionReverse(0);}if(e.Kind=="datum_plane"){doc.ClearSelection2(true);for(int i=0;i<entry.Item3.Length;i++)if(!Select(entry.Item3[i],i>0,i))throw new Exception("Cannot select rear datum points");if(doc.FeatureManager.InsertRefPlane(4,0,4,0,4,0)==null)throw new Exception("Cannot create rear plane");entity=doc.FeatureByPositionReverse(0);}var native=entity as Feature;if(native!=null)native.Name=e.Source;e.NativeReference=Ref(doc,entity);}
   Console.WriteLine("Saving joint references for owner "+batch.Key);Save(doc);File.WriteAllText(path,json.Serialize(blueprint));Activate(model);app.CloseDoc(doc.GetTitle());Console.WriteLine("Prepared joint datums for "+instances[batch.Key].Name2);
  }
 }
 static void RearJoints(){
  CheckOriginals();if(!File.Exists(Path.Combine(folder,"donor-ball-centers.json")))throw new Exception("Audit donor ball centers first");var path=Path.Combine(folder,"rear-joint-blueprint.json");var blueprint=File.Exists(path)?json.Deserialize<Blueprint>(File.ReadAllText(path)):RearBlueprint();if(!File.Exists(path))File.WriteAllText(path,json.Serialize(blueprint));foreach(var p in blueprint.Mates.Where(p=>p.Entities.All(e=>e.Kind=="axis")))p.Type=0;File.WriteAllText(path,json.Serialize(blueprint));RearReferences(blueprint,path);Activate(model);RearRetireReplacedMate();
  var installed=json.Deserialize<RearInstalled[]>(File.ReadAllText(Path.Combine(folder,"rear-installed.json")));foreach(var p in installed){var c=instances[p.Id];if(c.IsFixed()){model.ClearSelection2(true);c.Select4(false,null,false);((AssemblyDoc)model).UnfixComponent();}}
  foreach(var plan in blueprint.Mates){if(Mates().Any(p=>p.Item1.Name==plan.Name))continue;model.ClearSelection2(true);for(int i=0;i<2;i++){var e=plan.Entities[i];var entity=instances[e.Owner].GetCorresponding(Resolve(Owner(e.Owner),e.NativeReference));if(entity==null||!Select(entity,i>0,1))throw new Exception("Cannot select "+e.Source);}int error;var before=new HashSet<int>(Mates().Select(p=>p.Item1.GetID()));var mate=((AssemblyDoc)model).AddMate5(plan.Type,2,false,0,0,0,0,0,0,0,0,false,false,0,out error);if(mate==null||error!=1)throw new Exception("Rear mate failed "+plan.Name+": "+error);var added=Mates().Single(p=>!before.Contains(p.Item1.GetID()));added.Item1.Name=plan.Name;model.ClearSelection2(true);model.EditRebuild3();bool warning;var fault=added.Item1.GetErrorCode2(out warning);if(fault!=0&&!warning)throw new Exception("Rear mate unsolved "+plan.Name+": "+fault);Save(model);Console.WriteLine("Created "+plan.Name);}
  CheckOriginals();Write("rear-joints-complete.json",new{mates=blueprint.Mates.Select(m=>m.Name).ToArray(),originals_unchanged=true});
 }
 static void RearCenters(){
  var donor=app.GetOpenDocumentByName(@"H:\beamng project programs\MOCHI SUS\!DYNAMIC ASSEMBLY.SLDASM") as ModelDoc2;if(donor==null)throw new Exception("Donor must be open");var leaves=((object[])((AssemblyDoc)donor).GetComponents(false)).Cast<Component2>().ToArray();var rows=new List<object>();
  foreach(var name in new[]{"KNUCKLE LEFT ASSEMBLY-1/GE12C SPHERE-1","KNUCKLE LEFT ASSEMBLY-1/GE12C SPHERE-2","SHOCK ASSEMBLY III-1/GE15C SPHERE-1","SHOCK ASSEMBLY III-1/GE15C SPHERE-2"}){
   var c=leaves.Single(v=>v.Name2==name);var part=(PartDoc)c.GetModelDoc2();double[] sphere=null;foreach(Body2 body in part.GetBodies2(-1,false) as object[]??new object[0]){foreach(Face2 face in body.GetFaces() as object[]??new object[0]){var s=(Surface)face.GetSurface();if(s.IsSphere()){sphere=(double[])s.SphereParams;break;}}if(sphere!=null)break;}if(sphere==null)throw new Exception("No actual sphere surface in "+name);var world=Map(sphere.Take(3).ToArray(),c.Transform2,false);var expected=Map(new[]{0.0,0,0},c.Transform2,false);if(Norm(Sub(world,expected))>1e-7)throw new Exception("Ball origin assumption incorrect for "+name);rows.Add(new{name=name,local_center=sphere.Take(3).ToArray(),world_center=world,radius=sphere[3]});Console.WriteLine("Verified actual spherical center "+name);
  }Write("donor-ball-centers.json",rows);
 }
 static void RearVerify(){
  CheckOriginals();var b=json.Deserialize<Blueprint>(File.ReadAllText(Path.Combine(folder,"rear-joint-blueprint.json")));var installed=json.Deserialize<RearInstalled[]>(File.ReadAllText(Path.Combine(folder,"rear-installed.json")));model.EditRebuild3();if(MateFailures()!=0)throw new Exception("Mate errors before rear motion test");var baseline=instances.ToDictionary(p=>p.Key,p=>(double[])p.Value.Transform2.ArrayData);var known=new HashSet<int>(Mates().Select(m=>m.Item1.GetID()));var math=(MathUtility)app.GetMathUtility();var results=new List<object>();
  Action remove=()=>{foreach(var m in Mates().Where(m=>!known.Contains(m.Item1.GetID())).ToArray()){model.ClearSelection2(true);m.Item1.Select2(false,0);if(!model.Extension.DeleteSelection2(0))throw new Exception("Cannot remove rear motion driver");}};
  Action reset=()=>{foreach(var p in baseline)instances[p.Key].Transform2=(MathTransform)math.CreateTransform(p.Value);model.EditRebuild3();};
  Feature top=null;for(var f=model.FirstFeature() as Feature;f!=null;f=f.GetNextFeature() as Feature)if(f.Name=="Top Plane")top=f;if(top==null)throw new Exception("No root Top Plane");
  try{foreach(var side in new[]{"rl","rr"}){
   var wheel=installed.Single(p=>p.Side==side&&p.Role=="wheel");var arm=installed.Single(p=>p.Side==side&&p.Role=="trailing_arm");var upright=installed.Single(p=>p.Side==side&&p.Role=="upright");var axis=b.Mates.Single(m=>m.Name==side.ToUpperInvariant()+"_donor_wheel_bearing_axis").Entities.Single(e=>e.Owner==wheel.Id);
   // Drive the upright's toe-ball point vertically. Its point reference is already native and independent of wheel spin.
   var point=b.Mates.Single(m=>m.Name==side.ToUpperInvariant()+"_donor_toe_outer").Entities.Single(e=>e.Owner==upright.Id);
   foreach(var dy in new[]{.01,-.01,.03,-.03}){reset();var origin=Map(point.Point,instances[upright.Id].Transform2,false);var entity=instances[upright.Id].GetCorresponding(Resolve(Owner(upright.Id),point.NativeReference));model.ClearSelection2(true);if(!Select(entity,false,1)||!Select(top,true,1))throw new Exception("Cannot select rear motion driver");int error;var distance=Math.Abs(origin[1]+dy);var driver=((AssemblyDoc)model).AddMate5(5,2,origin[1]+dy<0,distance,distance,distance,0,0,0,0,0,false,false,0,out error);model.ClearSelection2(true);model.EditRebuild3();var moved=Map(point.Point,instances[upright.Id].Transform2,false);var actual=moved[1]-origin[1];var armDelta=((double[])instances[arm.Id].Transform2.ArrayData).Zip(baseline[arm.Id],(x,y)=>Math.Abs(x-y)).Max();var wheelPoint=Map(axis.Point,instances[wheel.Id].Transform2,false);var wheelAxis=Map(axis.Axis,instances[wheel.Id].Transform2,true);var errors=MateFailures();var passed=driver!=null&&error==1&&Math.Abs(actual-dy)<1e-6&&armDelta>1e-5&&errors==0;results.Add(new{side=side,test="vertical_travel",requested_m=dy,actual_m=actual,wheel_center=wheelPoint,wheel_axis=wheelAxis,arm_transform_delta=armDelta,mate_errors=errors,creation_status=error,passed=passed});Write("rear-motion-tests.json",results);Console.WriteLine((passed?"PASS ":"FAIL ")+side+" travel "+dy+": "+actual);remove();}
   reset();var c=instances[wheel.Id];var rotation=(MathTransform)math.CreateTransformRotateAxis((MathPoint)math.CreatePoint(Map(axis.Point,c.Transform2,false)),(MathVector)math.CreateVector(Map(axis.Axis,c.Transform2,true)),.1);var solved=c.SetTransformAndSolve3((MathTransform)c.Transform2.Multiply(rotation),true);model.EditRebuild3();var delta=((double[])c.Transform2.ArrayData).Zip(baseline[wheel.Id],(x,y)=>Math.Abs(x-y)).Max();results.Add(new{side=side,test="wheel_spin",solver=solved,delta=delta,passed=solved&&delta>1e-4&&MateFailures()==0});Write("rear-motion-tests.json",results);
  }}finally{remove();reset();model.ClearSelection2(true);Save(model);CheckOriginals();}
  if(results.Cast<object>().Any(v=>!object.Equals(v.GetType().GetProperty("passed").GetValue(v,null),true)))throw new Exception("Rear motion checks did not all pass; inspect rear-motion-tests.json");
  var project=RearProject();var workspace=(Dictionary<string,object>)project["JointWorkspace"];foreach(var m in RearArray(workspace,"Members"))m["PlacementFixed"]=((Component2)Resolve(model,(string)m["ComponentReference"])).IsFixed();File.WriteAllText(record.Copy+".beamng-project.json",json.Serialize(project));
  int count=0;var seen=new HashSet<string>();Action<object> validate=null;validate=v=>{var d=v as Dictionary<string,object>;if(d!=null){object kind,r,c;if(d.TryGetValue("Kind",out kind)&&object.Equals(kind,"body")&&d.TryGetValue("Reference",out r)&&d.TryGetValue("ComponentReference",out c)&&seen.Add((string)c+"|"+(string)r)){if(!(Resolve(model,(string)r) is Body2)||!(Resolve(model,(string)c) is Component2))throw new Exception("Rear replacement broke assignment");count++;}foreach(var child in d.Values)validate(child);}else{var a=v as object[];if(a!=null)foreach(var child in a)validate(child);}};validate(project);
  var total=Mates().Count();if(total!=39+b.Mates.Count)throw new Exception("Original mate set changed");app.CloseDoc(model.GetTitle());Load();model.EditRebuild3();if(Mates().Count()!=total||MateFailures()!=0)throw new Exception("Rear save/reopen mate validation failed");CheckOriginals();Write("rear-final-verification.json",new{copy=record.Copy,body_assignments=count,total_mates=total,rear_mates=b.Mates.Count,instances=instances.Count,logical_groups=RearArray(project,"Components").Length,save_reopen_passed=true,originals_unchanged=true,motion=results});Console.WriteLine("PASS rear motion, assignments and save/reopen");
 }
 static void RearDisplay(){
