  for(var f=model.FirstFeature() as Feature;f!=null;f=f.GetNextFeature() as Feature){var type=f.GetTypeName2();if(type=="RefPlane"||type=="RefAxis"||type=="RefPoint"||type=="ProfileFeature"||type=="3DProfileFeature"){model.ClearSelection2(true);if(!f.Select2(false,0))throw new Exception("Cannot hide reference "+f.Name);if(type=="ProfileFeature"||type=="3DProfileFeature")model.BlankSketch();else model.BlankRefGeom();}}
  model.ClearSelection2(true);model.ShowNamedView2("*Isometric",7);model.ViewZoomtofit2();model.GraphicsRedraw2();Save(model);model.SaveBMP(Path.Combine(folder,"rear-review.bmp"),1600,1000);CheckOriginals();Console.WriteLine("PASS rear review display prepared");
